package com.sakan.iptv;
import org.junit.Test;import static org.junit.Assert.*;import org.json.*;
public class ReleaseInfoTest {
 private final String repo="Owner/Player";
 private JSONObject release()throws Exception{return new JSONObject().put("draft",false).put("prerelease",false).put("assets",new JSONArray().put(new JSONObject().put("name","update.json").put("browser_download_url","https://github.com/Owner/Player/releases/download/v1.4/update.json")).put(new JSONObject().put("name","SakanIPTV-1.4.apk").put("size",1234).put("browser_download_url","https://github.com/Owner/Player/releases/download/v1.4/SakanIPTV-1.4.apk")));}
 private JSONObject manifest()throws Exception{return new JSONObject().put("packageName","com.sakan.iptv").put("versionCode",5).put("versionName","1.4").put("apkFileName","SakanIPTV-1.4.apk").put("sha256",new String(new char[64]).replace('\0','a')).put("sizeBytes",1234);}
 @Test public void readsStableManifestAndPinnedApkAsset()throws Exception{JSONObject r=release();assertTrue(ReleaseInfo.manifestUrl(r,repo).endsWith("update.json"));ReleaseInfo i=ReleaseInfo.parse(manifest(),r,repo);assertEquals(5,i.versionCode);assertEquals(1234,i.bytes);assertTrue(i.url.startsWith("https://github.com/Owner/Player/"));}
 @Test public void repositoryFieldCannotContainCredentialsOrUrls(){for(String value:new String[]{"https://github.com/Owner/Player","token-only","Owner/../Player","Owner/Player?token=secret","Owner/."}){try{ReleaseInfo.repository(value);fail(value);}catch(IllegalArgumentException expected){}}}
 @Test public void rejectsCrossRepositoryAndInsecureAssets()throws Exception{for(String link:new String[]{"http://github.com/Owner/Player/releases/download/v1/update.json","https://github.com/Other/Player/releases/download/v1/update.json","https://evil.test/Owner/Player/releases/download/v1/update.json","https://github.com@evil.test/Owner/Player/releases/download/v1/update.json"}){try{ReleaseInfo.trustedAsset(link,repo);fail(link);}catch(Exception expected){}}}
 @Test public void rejectsDraftOrPrerelease()throws Exception{for(String key:new String[]{"draft","prerelease"}){JSONObject r=release().put(key,true);try{ReleaseInfo.manifestUrl(r,repo);fail();}catch(Exception expected){}}}
 @Test public void rejectsDifferentPackageInvalidHashAndSizeMismatch()throws Exception{JSONObject[] bad={manifest().put("packageName","other.app"),manifest().put("sha256","bad"),manifest().put("sizeBytes",999),manifest().put("apkFileName","../app.apk")};for(JSONObject m:bad){try{ReleaseInfo.parse(m,release(),repo);fail();}catch(Exception expected){}}}
}
